/**
 * Returns the SVG definition for a given rating source.
 */
export function getRatingSourceDef(id: string): RatingSourceSvgDef | null {
  const key = id.toLowerCase().trim()
  return RATING_SOURCE_SVGS[key] ?? null
}

/**
 * Renders an inline <svg> snippet for Resvg embedding at a specific height and coordinates.
 */
export function renderRatingSourceSvg(
  id: string,
  height: number,
  options?: { x?: number; y?: number; topLight?: boolean }
): { svg: string; width: number; height: number } | null {
  const def = getRatingSourceDef(id)
  if (!def) return null
  const w = Math.round(height * def.aspect)
  const x = options?.x ?? 0
  const y = options?.y ?? 0
  
  const body = def.body

  const svg = `<svg x="${x}" y="${y}" width="${w}" height="${height}" viewBox="${def.viewBox}">${body}</svg>`
  return { svg, width: w, height }
}
